import{_ as e,o as t,c as r,ag as a}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"AppFooter（底部状态条积木）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/app-layout/docs/README-AppFooter.md","filePath":"docs/core/src/components/app-layout/docs/README-AppFooter.md"}'),p={name:"docs/core/src/components/app-layout/docs/README-AppFooter.md"};function d(s,o,l,c,i,n){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="appfooter-底部状态条积木" tabindex="-1">AppFooter（底部状态条积木） <a class="header-anchor" href="#appfooter-底部状态条积木" aria-label="Permalink to &quot;AppFooter（底部状态条积木）&quot;">​</a></h1><blockquote><p>底部状态条积木：零 props/emits/slots/expose——高度与样式完全由 <code>appStore.footerStyle</code> 驱动（inject APP_LAYOUT_APP_STORE_KEY 直取），随 store 变化 0.3s 过渡。 使用场景：AppLayout 组装 shell 吐出的 Footer 组件引用，经 AppBody #footer 槽落位（内置默认 AppShell 吐 AppFooter）。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>AppFooter 是族内最薄的积木：自身无任何对外接口（无 props / emits / slots / expose），只做一件事——inject 应用 store 窄化实例（<code>APP_LAYOUT_APP_STORE_KEY</code>），把 <code>appStore.footerStyle</code> 绑到根盒 <code>:style</code> 上渲染底部状态条（高度 / 背景 / 圆角 / 横向内呼吸由 store 驱动，阴影走主题 var）。显隐与高度变化全部由 AppLayout/store 侧控制，消费方不直接挂载、也无可配置项。</p><p><strong>面貌三项与 AppHeader 同源同口径</strong>（对称积木，[MUST] 一起改）：</p><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>覆盖法</th></tr></thead><tbody><tr><td>背景</td><td><code>APP_LAYOUT_FOOTER_CONFIG.background ?? 主题 bodyColor</code></td><td>配 <code>background</code></td></tr><tr><td>圆角</td><td><code>var(--dc-core-radius, var(--el-border-radius-base))</code></td><td><code>APP_LAYOUT_FOOTER_CONFIG.style.borderRadius</code></td></tr><tr><td>横向内呼吸</td><td>间距阶梯<strong>模块档</strong>（默认 <strong>8px</strong>）</td><td><code>APP_LAYOUT_FOOTER_CONFIG.style.padding</code></td></tr></tbody></table><p>圆角 / padding 的默认值在 <code>...cfg.style</code> 展开<strong>之前</strong>写入 ⇒ 逃生舱同名键恒赢；<code>height</code> / <code>marginTop</code> / <code>background</code> / <code>color</code> 仍是引擎托管键（展开之后，压过外部）。</p><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>零配置、零 props——样式与显隐全由 <code>appStore.footerStyle</code> 驱动</strong>（随 store 变化 0.3s 过渡）：要改高度/显隐走 store（footerStyle），[MUST NOT] 给 AppFooter 加 props 透传；消费方不直接挂载（内置经典布局已经 shell → AppBody #footer 自动落位）。<strong>完整能力演示</strong>（NoFooter 变体）：<code>apps/reference/src/pages/app-layout/layout/</code></li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><p>无</p><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>勿给 AppFooter 加 props 透传</strong>：其样式是 store 真相源（footerStyle），不是 prop 驱动——要改高度/显隐走 store</li><li>消费方不应直接挂载——内置经典布局已经 shell → AppBody #footer 自动落位</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>落位链：AppLayout → AppShell 默认 scoped slot（<code>AppShellDefaultSlotScope</code>：<code>{ Footer: Component }</code>）→ AppBody #footer</li><li>store：<code>APP_LAYOUT_APP_STORE_KEY</code>（footerStyle 驱动）</li><li>范式页：<code>apps/reference/src/pages/app-layout/layout/</code>（NoFooter 变体）</li></ul>',22)])])}const A=e(p,[["render",d]]);export{u as __pageData,A as default};
